def operate2( L ):
    expression = ''
    if ( L[0] == 'NOT' ):
        expression = '~%s' % L[1]
    elif ( L[0] == 'NAND' ):
        expression = '~(%s & %s)' % ( L[1],L[2] )
    else:
        expression = '~(%s | %s)' % ( L[1],L[2] )
    return expression

def generate_2v( resdict, BIT, G ):
    VAR = [ 'x%d' % i for i in range( BIT )]
    EXPRESSION = []
    for g in range( G ):
        L = []
        gate = resdict['GATE'][str(g)][2:]

        a0 = resdict['A0'][str(g)]
        if ( a0[0:2] == '0x' ):
            a0 = bin( int( a0, 16 ) )[2:].zfill( BIT + g )
        else:
            a0 = a0[2:]

        a1 = resdict['A1'][str(g)]
        if ( a1[0:2] == '0x' ):
            a1 = bin( int( a1, 16 ) )[2:].zfill( BIT + g )
        else:
            a1 = a1[2:]

        if ( a0 == a1 ):
            L.append( 'NOT' )
            VAR.append( 'NOT_%d' % g )
        elif ( gate == '0' ):
            L.append( 'NAND' )
            VAR.append( 'NAND_%d' % g )
        else:
            L.append( 'NOR' )
            VAR.append( 'NOR_%d' % g )

        for i in range( BIT + g ):
            if ( a0[i] == '1' ):
                L.append( VAR[i] )
            if ( a1[i] == '1' ):
                L.append( VAR[i] )
        
        EXPRESSION.append( operate2(L) )
    

    with open( "xxx/sbox2.v", "w+" ) as f:
        f.write( "module sbox2(\n" )
        f.write( "\tinput [3:0] sbin,\n" )
        f.write( "\toutput [3:0] sbout\n" )
        f.write( ");\n\n" )

        f.write( "wire x0,x1,x2,x3,y0,y1,y2,y3;\n" )
        f.write( "wire " + ",".join(VAR[BIT:]) + ";\n\n" )
        f.write( "assign {x0,x1,x2,x3} = sbin;\n" )
        f.write( "assign sbout = {y0,y1,y2,y3};\n\n" )

        for i in range( G ):
            f.write( "assign %s = %s;\n" % ( VAR[BIT+i], EXPRESSION[i] ) )
    
        f.write( "\n" )
        for n in range( BIT ):
            ya = resdict['YA'][str(n)]
            if ( ya[0:2] == '0x' ):
                ya = bin( int( ya, 16 ) )[2:].zfill( BIT + G )
            else:
                ya = ya[2:]

            for i in range( BIT + G ):
                if ( ya[i] == '1' ):
                    f.write( "assign y%d = %s;\n" % ( n, VAR[i] ) )

        f.write( "\nendmodule\n" )

def operate3( L, out ):
    expression = ''
    if ( L[0] == 'NOT' ):
        expression = 'assign %s = ~%s;' % ( out,L[1] )
    elif ( L[0] == 'NAND' ):
        expression = 'NAND %s (.in1(%s), .in2(%s), .out(%s));' % ( out.lower(),L[1],L[2],out )
    else:
        expression = 'NOR %s (.in1(%s), .in2(%s), .out(%s));' % ( out.lower(),L[1],L[2],out )
    return expression

def generate_3v( resdict, BIT, G ):
    VAR = [ 'x%d' % i for i in range( BIT )]
    EXPRESSION = []
    for g in range( G ):
        L = []
        gate = resdict['GATE'][str(g)][2:]

        a0 = resdict['A0'][str(g)]
        if ( a0[0:2] == '0x' ):
            a0 = bin( int( a0, 16 ) )[2:].zfill( BIT + g )
        else:
            a0 = a0[2:]

        a1 = resdict['A1'][str(g)]
        if ( a1[0:2] == '0x' ):
            a1 = bin( int( a1, 16 ) )[2:].zfill( BIT + g )
        else:
            a1 = a1[2:]

        if ( a0 == a1 ):
            L.append( 'NOT' )
            VAR.append( 'NOT_%d' % g )
        elif ( gate == '0' ):
            L.append( 'NAND' )
            VAR.append( 'NAND_%d' % g )
        else:
            L.append( 'NOR' )
            VAR.append( 'NOR_%d' % g )

        for i in range( BIT + g ):
            if ( a0[i] == '1' ):
                L.append( VAR[i] )
            if ( a1[i] == '1' ):
                L.append( VAR[i] )
        
        EXPRESSION.append( operate3( L, VAR[BIT+g] ) )
    

    with open( "xxx/sbox3.v", "w+" ) as f:
        f.write( "module NOR(\n" )
        f.write( "\tinput in1,\n" )
        f.write( "\tinput in2,\n" )
        f.write( "\toutput out\n" )
        f.write( ");\n" )
        f.write( "assign out = ~(in1 | in2);\n" )
        f.write( "endmodule\n\n" )

        f.write( "module NAND(\n" )
        f.write( "\tinput in1,\n" )
        f.write( "\tinput in2,\n" )
        f.write( "\toutput out\n" )
        f.write( ");\n" )
        f.write( "assign out = ~(in1 & in2);\n" )
        f.write( "endmodule\n\n" )

        f.write( "module sbox3(\n" )
        f.write( "\tinput [3:0] sbin,\n" )
        f.write( "\toutput [3:0] sbout\n" )
        f.write( ");\n\n" )

        f.write( "wire x0,x1,x2,x3,y0,y1,y2,y3;\n" )
        f.write( "wire " + ",".join(VAR[BIT:]) + ";\n\n" )
        f.write( "assign {x0,x1,x2,x3} = sbin;\n" )
        f.write( "assign sbout = {y0,y1,y2,y3};\n\n" )

        for i in range( G ):
            f.write( EXPRESSION[i] + "\n" )
    
        f.write( "\n" )
        for n in range( BIT ):
            ya = resdict['YA'][str(n)]
            if ( ya[0:2] == '0x' ):
                ya = bin( int( ya, 16 ) )[2:].zfill( BIT + G )
            else:
                ya = ya[2:]

            for i in range( BIT + G ):
                if ( ya[i] == '1' ):
                    f.write( "assign y%d = %s;\n" % ( n, VAR[i] ) )

        f.write( "\nendmodule\n" )


